  --bg: #ffffff; --surface: #eef6f8; --ink: #13293a; --muted: #5a6f7e; --line: #d5e4e9;
  --navy: #0a2a40; --teal: #0b7e93; --orange: #ff8d1c; --link: #0a6d80; --btn-ink: #0a2a40;
  --display: "Be Vietnam Pro", "Segoe UI", Roboto, Arial, sans-serif;
  --body: "Be Vietnam Pro", "Segoe UI", Roboto, Arial, sans-serif;
}
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) {
  --bg: #0b1a24; --surface: #12293a; --ink: #e6eff3; --muted: #9db3c0; --line: #22405a;
